      SUBROUTINE RETAINCC     STORE VALUES OF PARAMETERS, MATRICES, AND LOGICAL VARIABLESC     AT BEGINNING OF SECTION WHERE FITTING OCCURSCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'COSS.CIN'      INCLUDE 'COPS.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2S.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0F.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM1E.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8B.CIN'      INCLUDE 'ELM8E.CIN'      INCLUDE 'ELM9.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'ELM22A.CIN'      INCLUDE 'ELM24B.CIN'      INCLUDE 'ELM24C.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'ELM31B.CIN'      INCLUDE 'ELS0B.CIN'      INCLUDE 'ELS1A.CIN'      INCLUDE 'ELS1D.CIN'      INCLUDE 'ELS7B.CIN'      INCLUDE 'ELS8A.CIN'      INCLUDE 'ELS8B.CIN'      INCLUDE 'ELS8C.CIN'      INCLUDE 'ELS10E.CIN'      INCLUDE 'ELS13A.CIN'      INCLUDE 'ELS16A.CIN'      INCLUDE 'ELS16B.CIN'      INCLUDE 'ELS20.CIN'      INCLUDE 'ELS22A.CIN'      INCLUDE 'ELS24A.CIN'      INCLUDE 'ELS24B.CIN'      INCLUDE 'ELS24C.CIN'      INCLUDE 'ELS26B.CIN'      INCLUDE 'ELS31.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'ETAP.CIN'      INCLUDE 'ETAPS.CIN'      INCLUDE 'ETASC.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'OCP.CIN'      INCLUDE 'OCPS.CIN'      INCLUDE 'OCS.CIN'      INCLUDE 'SEEDS.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'SIS.CIN'CC     LOCAL VARIABLESC      INTEGER         IPP, J, K, K1, K2, NC-----------------------------------------------------------------------------C      NUMS = NUM      NDIFS = NDIF      LCS = LC      TOTRTS = TOTROT      CALL MRETC      DO 110 J = 1, 6      DO 110 K = 1, 6  110 SIS(J,K) = SI(J,K)      DO 120 J = 1, 6  120 COSS(J) = CO(J)      RIS = RI      PSIXOS = PSIXO      PSIYOS = PSIYO      SOFAS = SOFA      DO 130 J = 1, 6  130 COFS(J) = COF(J)      DO 135 J = 1, 6  135 ETAS(J) = ETA(J)      RAYS = RAY      NMRKS = NMARK      NMRKSS = NMARKS      MKGS = MKG      NDIFMS = NDIFM      DO 137 J = 1, 4  137 OCPS(J) = OCP(J)C      IF (.NOT. LAY .AND. .NOT. ALIGN) GO TO 200      DO 140 J = 1, 4      DO 140 K1 = 1, 3      DO 140 K2 = 1, 3  140 OS(J,K1,K2) = O(J,K1,K2)      DO 150 J = 1, 4      DO 150 K = 1, 3  150 X0S(J,K) = X0(J,K)      RORCS = RORC      DO 160 J = 1, 6  160 VMS(J) = VM(J)C  200 LAYS = LAY      R1PS = R1P      FOTLTS = FOTILT      SMS = SM      PREFS = PREFC      IF (.NOT. ALIGN) GO TO 250      DO 210 J = 1, 3      DO 210 K1 = 1, 6      DO 210 K2 = 1, 6      SIOLS(J,K1,K2) = SIOL(J,K1,K2)  210 RCOS(J,K1,K2) = RCO(J,K1,K2)      DO 220 J = 1, 3      DO 220 K = 1, 6  220 COLDS(J,K) = COLD(J,K)      DO 230 J = 1, 6      DO 230 K = 1, 6  230 R2OS(J,K) = R2O(J,K)      DO 240 J = 1, 3      SPOS(J) = SPO(J)  240 RCPOS(J) = RCPO(J)      R2POS = R2POC  250 ATWS = ATWORKC      DO 260 J = 1, 20      REGS(J) = REG(J)  260 LREGS(J) = LREG(J)      IPS = IP      IF (IP .LT. 0 .OR. IP .GT. 4) THEN        WRITE (NOUT,9005) IP 9005   FORMAT (' IN RETAIN, IP = ',I5)        FLUSHL = .TRUE.        GO TO 500      ENDIF      IF (IPS .GT. 0) THEN        DO 265 IPP = 1, IPS        ICS(IPP) = IC(IPP)  265   ISS(IPP) = IS(IPP)      ENDIF      NDLEVS = NDLEV      IF (NDLEVS .GT. 0) THEN        DO 280 N = 1, NDLEV        NDCS(N) = NDC(N)        NDSS(N) = NDS(N)  280   NDNS(N) = NDN(N)      ENDIFC  300 DO 305 J = 1, 4  305 PRAN2S(J) = PRAN2(J)      PRAN3S = PRAN3      DO 310 J = 1, 15  310 PRAN4S(J) = PRAN4(J)      DO 320 J = 1, 5  320 PRAN5S(J) = PRAN5(J)      DO 330 J = 1, 6  330 PRAN7S(J) = PRAN7(J)      DO 340 J = 1, 4  340 PRN11S(J) = PRAN11(J)      DO 350 J = 1, 4  350 PRN18S(J) = PRAN18(J)      DO 360 J = 1, 3  360 PRN19S(J) = PRAN19(J)      PRN20S = PRAN20      DO 370 J = 1, 4  370 PRN25S(J) = PRAN25(J)      DO 380 J = 1, 9  380 PRN28S(J) = PRAN28(J)      DO 390 J = 1, 5  390 PRN34S(J) = PRAN34(J)      DO 400 J = 1, 6  400 PRN43S(J) = PRAN43(J)C      BDBIS = BDBI      APBIS(1) = APBI(1)      APBIS(2) = APBI(2)      LAYKIS = LAYKI      LAYLIS = LAYLI      LAYXIS = LAYXI      RAB1IS = RAB1I      RAB2IS = RAB2I      RMPSIS = RMPSI      RNMSIS = RNMSI      VRNIS = VRNI      NPNIS = NPNI      BDBPIS = BDBPIC      CALL RANGET(ISEEDS)  500 RETURN      END